@SuppressWarnings("BigDecimalMethodWithoutRoundingCalled") private static String formatBalance(long satoshis){
  var btcFormat=new DecimalFormat("###,##0.00000000");
  var satoshiDivisor=new BigDecimal(100000000);
  try {
    return btcFormat.format(BigDecimal.valueOf(satoshis).divide(satoshiDivisor));
  } catch (ArithmeticException e) {
    return btcFormat.format(BigDecimal.valueOf(satoshis).divide(satoshiDivisor, 8, RoundingMode.HALF_UP));
  }
}
